#!/usr/bin/env bash
# boussole.sh — un outil que tu n'as jamais vu
aide() {
  echo 'Utilisation : bash boussole.sh -c CAP -p PAS'
  echo 'Dit où tu arrives en partant du refuge.'
  echo '  -c CAP      ''le cap : nord, sud, est ou ouest'
  echo '  -p PAS      ''le nombre de pas (1 à 9)'
  echo '  -h, --help  ''cette aide'
}
if [ "${1:-}" = "--help" ]; then aide; exit 0; fi
cap=""
pas=""
while getopts "c:p:h" opt; do
  case $opt in
    c) cap=$OPTARG ;;
    p) pas=$OPTARG ;;
    h) aide; exit 0 ;;
    *) aide >&2; exit 2 ;;
  esac
done
if [ -z "$cap" ] || [ -z "$pas" ]; then aide >&2; exit 2; fi
case "$cap:$pas" in
  nord:1) lieu=grotte-bleue ;;
  nord:2) lieu=col-du-vent ;;
  nord:3) lieu=pic-noir ;;
  nord:4) lieu=pont-de-glace ;;
  nord:5) lieu=cascade ;;
  nord:6) lieu=vieux-refuge ;;
  nord:7) lieu=vieux-refuge ;;
  nord:8) lieu=pic-noir ;;
  nord:9) lieu=crete-rouge ;;
  sud:1) lieu=glacier-blanc ;;
  sud:2) lieu=source-chaude ;;
  sud:3) lieu=col-du-vent ;;
  sud:4) lieu=pic-noir ;;
  sud:5) lieu=combe-verte ;;
  sud:6) lieu=moraine ;;
  sud:7) lieu=grotte-bleue ;;
  sud:8) lieu=crete-rouge ;;
  sud:9) lieu=vieux-refuge ;;
  est:1) lieu=source-chaude ;;
  est:2) lieu=lac-gele ;;
  est:3) lieu=pont-de-glace ;;
  est:4) lieu=pic-noir ;;
  est:5) lieu=crete-rouge ;;
  est:6) lieu=pic-noir ;;
  est:7) lieu=pont-de-glace ;;
  est:8) lieu=source-chaude ;;
  est:9) lieu=pont-de-glace ;;
  ouest:1) lieu=source-chaude ;;
  ouest:2) lieu=glacier-blanc ;;
  ouest:3) lieu=vieux-refuge ;;
