# boussole.sh — un outil que tu n'as jamais vu
aide() {
  echo 'Utilisation : bash boussole.sh -c CAP -p PAS'
  echo 'Dit où tu arrives en partant du refuge.'
  echo '  -c CAP      ''le cap : nord, sud, est ou ouest'
  echo '  -p PAS      ''le nombre de pas (1 à 9)'
  echo '  -h, --help  ''cette aide'
}
if [ "${1:-}" = "--help" ]; then aide; exit 0; fi
cap=""
pas=""
while getopts "c:p:h" opt; do
  case $opt in
    c) cap=$OPTARG ;;
    p) pas=$OPTARG ;;
    h) aide; exit 0 ;;
    *) aide >&2; exit 2 ;;
  esac
done
if [ -z "$cap" ] || [ -z "$pas" ]; then aide >&2; exit 2; fi
case "$cap:$pas" in
  nord:1) lieu=vieux-refuge ;;
  nord:2) lieu=lac-gele ;;
  nord:3) lieu=chapelle ;;
  nord:4) lieu=source-chaude ;;
  nord:5) lieu=belvedere ;;
  nord:6) lieu=chapelle ;;
  nord:7) lieu=foret-de-pins ;;
  nord:8) lieu=foret-de-pins ;;
  nord:9) lieu=crete-rouge ;;
  sud:1) lieu=moraine ;;
  sud:2) lieu=crete-rouge ;;
  sud:3) lieu=vieux-refuge ;;
  sud:4) lieu=glacier-blanc ;;
  sud:5) lieu=pic-noir ;;
  sud:6) lieu=chapelle ;;
  sud:7) lieu=grotte-bleue ;;
  sud:8) lieu=belvedere ;;
  sud:9) lieu=lac-gele ;;
  est:1) lieu=grotte-bleue ;;
  est:2) lieu=glacier-blanc ;;
  est:3) lieu=source-chaude ;;
  est:4) lieu=glacier-blanc ;;
  est:5) lieu=cascade ;;
  est:6) lieu=pic-noir ;;
  est:7) lieu=pont-de-glace ;;
  est:8) lieu=combe-verte ;;
  est:9) lieu=moraine ;;
  ouest:1) lieu=moraine ;;
  ouest:2) lieu=combe-verte ;;
  ouest:3) lieu=combe-verte ;;
  ouest:4) lieu=crete-rouge ;;
  ouest:5) lieu=glacier-blanc ;;
  ouest:6) lieu=roc-perce ;;
  ouest:7) lieu=cascade ;;
  ouest:8) lieu=roc-perce ;;
  ouest:9) lieu=col-du-vent ;;
  *) lieu=brume ;;
esac
echo 'Tu arrives à :' "$lieu"
echo "$lieu" > arrivee.txt

